// gestalt :: .github/scripts/css.mjs
// bundles and minifies the css listed in .github/config.js (css: { output: [files] }).
//   node .github/scripts/css.mjs
//
// no esbuild / lightningcss on purpose: both parse the css and lower or reject what they
// do not know yet (@function, if(), attr() with type()). this only moves text: it inlines
// relative @imports and removes comments and whitespace, so new syntax passes untouched.

import { readFile, writeFile } from 'node:fs/promises';
import { dirname, relative, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT   = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const config = (await import(pathToFileURL(resolve(ROOT, '.github/config.js')).href)).default;

// @import url('./x.css') layer(name) supports(cond) media;  (url() or a plain string)
const IMPORT = /@import\s+(?:url\(\s*(['"]?)([^'")]+)\1\s*\)|(['"])([^'"]+)\3)\s*([^;]*);/g;

// :::::: INLINE

async function inline (file, seen = new Set) {
  if (seen.has(file)) throw new Error(`circular @import: ${relative(ROOT, file)}`);
  seen = new Set(seen).add(file);

  const source = stripComments(await readFile(file, 'utf8'));
  let output   = '';
  let last     = 0;

  for (const match of source.matchAll(IMPORT)) {
    const href       = match[2] ?? match[4];
    const conditions = match[5].trim();
    output += source.slice(last, match.index);
    last    = match.index + match[0].length;

    // remote imports stay imports. they are only valid at the top, so they move to the start of the bundle
    if (/^(https?:)?\/\//.test(href)) { output += match[0]; continue; }

    output += wrap(await inline(resolve(dirname(file), href), seen), conditions);
  }

  return output + source.slice(last);
}

// layer(x) supports(y) media -> @layer x { @supports y { @media media { … } } }
function wrap (css, conditions) {
  const layer    = conditions.match(/^layer(?:\(([^)]*)\))?\s*/);
  let rest       = layer ? conditions.slice(layer[0].length) : conditions;
  const supports = rest.match(/^supports\(((?:[^()]|\([^()]*\))*)\)\s*/);
  if (supports) rest = rest.slice(supports[0].length);

  if (rest)     css = `@media ${rest}{${css}}`;
  if (supports) css = `@supports (${supports[1]}){${css}}`;
  if (layer)    css = `@layer ${layer[1] ?? ''}{${css}}`;
  return css;
}

// :::::: MINIFY
// strings are copied as they are, everything else loses comments and collapses whitespace.
// spaces go only around { } ; , — never around : (a :hover is not a:hover), + (calc)
// or > (type(<color> <length>+) and other value syntax)

function stripComments (css) {
  return scan(css, chunk => chunk);
}

function minify (css) {
  return scan(css, chunk => chunk
    .replace(/\s+/g, ' ')
    .replace(/\s*([{};,])\s*/g, '$1')
    .replace(/;+}/g, '}'))
    .trim();
}

// calls edit for every run of text outside strings and comments
function scan (css, edit) {
  let output = '', chunk = '';
  for (let index = 0; index < css.length; index++) {
    const char = css[index];
    if (char === '/' && css[index + 1] === '*') {
      const end = css.indexOf('*/', index + 2);
      index     = end === -1 ? css.length : end + 1;
      chunk    += ' ';
    } else if (char === '"' || char === "'") {
      let end = index + 1;
      while (end < css.length && css[end] !== char) end += css[end] === '\\' ? 2 : 1;
      output += edit(chunk) + css.slice(index, end + 1);
      chunk   = '';
      index   = end;
    } else chunk += char;
  }
  return output + edit(chunk);
}

// remote @imports and @charset must come first, after them the @layer order statements
function hoist (css) {
  const head = [];
  css = css.replace(/@(?:charset|import)\s[^;]*;/g, rule => { head.push(rule); return ''; });
  return head.join('') + css;
}

// :::::: RUN

for (const [output, files] of Object.entries(config.css ?? {})) {
  const parts = [];
  for (const file of files) parts.push(await inline(resolve(ROOT, file)));

  const css = minify(hoist(parts.join('\n')));
  await writeFile(resolve(ROOT, output), `/* ${output} :: generated by .github/scripts/css.mjs from .github/config.js, do not edit */\n${css}\n`);
  console.log(`${output}  ${files.length} file(s)  ${(css.length / 1024).toFixed(1)} KB`);
}
